SELECT asset_id, project_id, asset_name, assets_type, assets_stage, security_level, created_by_employee_id, created_at, file_path, file_size, description FROM project_assets
AND project_id = #{projectId}
AND asset_name LIKE CONCAT('%', #{assetName}, '%')
AND assets_type = #{assetsType}
AND assets_stage = #{assetsStage}
AND security_level = #{securityLevel}
AND created_by_employee_id = #{createdByEmployeeId}
ORDER BY created_at DESC
LIMIT #{pageSize} OFFSET #{pageNum}

SELECT COUNT(*)
FROM project_assets


        AND project_id = #{projectId}


